// TestCustomRule_RotateAgedKeys verifies the end-to-end flow for the
// canonical bank use case: a CEL rule generated by the rotate_aged_keys
// template revokes a key that's older than the threshold and writes
// the expected audit + webhook payload.
func TestCustomRule_RotateAgedKeys(t *testing.T) {
	if testing.Short() {
		t.Skip("requires postgres")
	}
	db, cleanup := testutil.NewTestDB(t)
	defer cleanup()

	// Seed: one user, two keys — one old (200 days), one new.
	uid := uuid.New()
	user := models.User{BaseModel: models.BaseModel{ID: uid}, Email: "u@x", Username: "u", IsActive: true}
	if err := db.Create(&user).Error; err != nil {
		t.Fatal(err)
	}
	old := time.Now().Add(-200 * 24 * time.Hour)
	new := time.Now().Add(-3 * 24 * time.Hour)
	keyOld := models.Key{
		BaseModel: models.BaseModel{ID: uuid.New(), CreatedAt: old},
		Key:       "pllm_ak_old", KeyHash: "h_old", KeyPrefix: "old",
		Name: "old-key", IsActive: true, UserID: &uid, Type: models.KeyTypeAPI,
	}
	keyNew := models.Key{
		BaseModel: models.BaseModel{ID: uuid.New(), CreatedAt: new},
		Key:       "pllm_ak_new", KeyHash: "h_new", KeyPrefix: "new",
		Name: "new-key", IsActive: true, UserID: &uid, Type: models.KeyTypeAPI,
	}
	if err := db.Create(&keyOld).Error; err != nil {
		t.Fatal(err)
	}
	if err := db.Create(&keyNew).Error; err != nil {
		t.Fatal(err)
	}

	// Build the rule from the template — same path the API handler takes.
	tmpl := FindTemplate("rotate_aged_keys")
	if tmpl == nil {
		t.Fatal("template missing")
	}
	expr, err := tmpl.BuildExpr(map[string]any{"days": 90})
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	spec := &models.LifecycleCustomRule{
		BaseModel: models.BaseModel{ID: uuid.New()},
		Name:      "test_rotation_90d",
		Scan:      tmpl.Scan,
		Match:     expr,
		Action:    tmpl.Action,
		Reason:    tmpl.BuildReason(map[string]any{"days": 90}),
		Enabled:   true,
	}
	cr, err := NewCustomRule(spec)
	if err != nil {
		t.Fatalf("compile: %v", err)
	}

	emitter := &fakeEmitter{}
	cfg := Config{DryRun: false}
	res := cr.Run(context.Background(), db, cfg, emitter)

	if len(res.Actions) != 1 {
		t.Fatalf("expected 1 action, got %d (scanned=%d, err=%q)", len(res.Actions), res.Scanned, res.Err)
	}
	if res.Actions[0].ResourceID != keyOld.ID.String() {
		t.Fatalf("expected old key id, got %s", res.Actions[0].ResourceID)
	}

	// Old key should be revoked.
	var got models.Key
	if err := db.First(&got, "id = ?", keyOld.ID).Error; err != nil {
		t.Fatal(err)
	}
	if got.IsActive {
		t.Fatal("expected old key to be revoked")
	}
	if got.RevokedAt == nil {
		t.Fatal("expected RevokedAt set")
	}

	// New key untouched.
	var stillFresh models.Key
	if err := db.First(&stillFresh, "id = ?", keyNew.ID).Error; err != nil {
		t.Fatal(err)
	}
	if !stillFresh.IsActive {
		t.Fatal("new key should not have been revoked")
	}

	// Audit row tagged with the rule name.
	var audits []models.Audit
	db.Where("event_type = ? AND key_id = ?", models.AuditEventLifecycle, keyOld.ID).Find(&audits)
	if len(audits) != 1 {
		t.Fatalf("expected 1 audit row, got %d", len(audits))
	}
	if string(audits[0].NewValues) == "" || !contains(string(audits[0].NewValues), "test_rotation_90d") {
		t.Fatalf("audit NewValues missing rule_name: %s", string(audits[0].NewValues))
	}

	// Webhook fired with lifecycle.custom event type.
	if len(emitter.events) != 1 {
		t.Fatalf("expected 1 webhook event, got %d", len(emitter.events))
	}
	if emitter.events[0].Type != models.WebhookEventLifecycleCustom {
		t.Fatalf("expected lifecycle.custom event, got %q", emitter.events[0].Type)
	}
}

// TestCustomRule_DryRunNoMutation verifies dry-run logs the action
// but doesn't mutate the row. Master safety property: a fresh-install
// daemon never breaks anything before the operator opts in.
func TestCustomRule_DryRunNoMutation(t *testing.T) {
	if testing.Short() {
		t.Skip("requires postgres")
	}
	db, cleanup := testutil.NewTestDB(t)
	defer cleanup()

	uid := uuid.New()
	user := models.User{BaseModel: models.BaseModel{ID: uid}, Email: "u@x", Username: "u", IsActive: true}
	if err := db.Create(&user).Error; err != nil {
		t.Fatal(err)
	}
	old := time.Now().Add(-200 * 24 * time.Hour)
	k := models.Key{
		BaseModel: models.BaseModel{ID: uuid.New(), CreatedAt: old},
		Key:       "pllm_ak_dry", KeyHash: "h_dry", KeyPrefix: "dry",
		Name: "dry", IsActive: true, UserID: &uid, Type: models.KeyTypeAPI,
	}
	if err := db.Create(&k).Error; err != nil {
		t.Fatal(err)
	}

	tmpl := FindTemplate("rotate_aged_keys")
	expr, _ := tmpl.BuildExpr(map[string]any{"days": 90})
	spec := &models.LifecycleCustomRule{
		BaseModel: models.BaseModel{ID: uuid.New()},
		Name:      "dry_test",
		Scan:      tmpl.Scan,
		Match:     expr,
		Action:    tmpl.Action,
		Reason:    "dry test",
		Enabled:   true,
	}
	cr, _ := NewCustomRule(spec)

	emitter := &fakeEmitter{}
	cfg := Config{DryRun: true}
	res := cr.Run(context.Background(), db, cfg, emitter)

	if len(res.Actions) != 1 {
		t.Fatalf("expected 1 dry-run action, got %d", len(res.Actions))
	}
	if !res.Actions[0].DryRun {
		t.Fatal("action should be marked DryRun=true")
	}
	// The key must still be active — dry-run never mutates.
	var got models.Key
	db.First(&got, "id = ?", k.ID)
	if !got.IsActive {
		t.Fatal("dry-run revoked the key — should be a no-op")
	}
	if len(emitter.events) != 0 {
		t.Fatal("dry-run should not emit webhooks")
	}
}

// TestCustomRule_FlagStaleDrafts confirms the flag-action path on a
// different scan target (use_cases). Asserts the compliance_flag flips
// and the audit row records the rule.
func TestCustomRule_FlagStaleDrafts(t *testing.T) {
	if testing.Short() {
		t.Skip("requires postgres")
	}
	db, cleanup := testutil.NewTestDB(t)
	defer cleanup()

	uc := models.UseCase{
		BaseModel: models.BaseModel{ID: uuid.New(), CreatedAt: time.Now().Add(-90 * 24 * time.Hour)},
		Name:      "stale-uc", Slug: "stale-uc", Status: models.UseCaseStatusDraft,
	}
	if err := db.Create(&uc).Error; err != nil {
		t.Fatal(err)
	}

	tmpl := FindTemplate("flag_stale_drafts")
	expr, _ := tmpl.BuildExpr(map[string]any{"days": 30})
	spec := &models.LifecycleCustomRule{
		BaseModel: models.BaseModel{ID: uuid.New()},
		Name:      "flag_drafts_30d",
		Scan:      tmpl.Scan,
		Match:     expr,
		Action:    tmpl.Action,
		Reason:    tmpl.BuildReason(map[string]any{"days": 30}),
		Enabled:   true,
	}
	cr, err := NewCustomRule(spec)
	if err != nil {
		t.Fatalf("compile: %v", err)
	}

	emitter := &fakeEmitter{}
	res := cr.Run(context.Background(), db, Config{DryRun: false}, emitter)

	if len(res.Actions) != 1 {
		t.Fatalf("expected 1 action, got %d (scanned=%d)", len(res.Actions), res.Scanned)
	}
	var got models.UseCase
	if err := db.First(&got, "id = ?", uc.ID).Error; err != nil {
		t.Fatal(err)
	}
	if !got.ComplianceFlag {
		t.Fatal("expected compliance_flag=true after rule fired")
	}
	if got.ComplianceFlagReason == "" {
		t.Fatal("expected compliance_flag_reason populated")
	}
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}
